        if isinstance(d, dict):
            for k in keys:
                if k in d:
                    return d[k]
        for k in keys:
            try:
                return obj[k]
            except Exception:
                pass
        return default

    coords = get_value(instance, ("coords", "coordinates", "positions", "locs", "points"), None)
    demands = get_value(instance, ("demands", "demand"), None)
    capacity = get_value(instance, ("capacity", "vehicle_capacity", "cap"), None)
    depot = get_value(instance, ("depot", "depot_id", "depot_index"), 0)
    customers = get_value(instance, ("customers", "nodes", "vertices", "points"), None)

    if customers is None:
        if coords is not None:
            customers = list(range(len(coords)))
        elif demands is not None:
            if isinstance(demands, dict):
                customers = list(demands.keys())
            else:
                customers = list(range(len(demands)))
        else:
            customers = []
    else:
        customers = list(customers)

    if depot in customers:
        customers = [c for c in customers if c != depot]

    if isinstance(demands, dict):
        def dem_get(i):
            return demands.get(i, 1)
    elif isinstance(demands, (list, tuple)):
        def dem_get(i):
            return demands[i] if 0 <= i < len(demands) else 1
    else:
        def dem_get(i):
            return 1

    if capacity is None:
        total = 0
        for c in customers:
            total += dem_get(c)
        capacity = total if total > 0 else 1

    def coord_of(i):
        if coords is None:
            return None
        try:
            return coords[i]
        except Exception:
            return None

    def dist(i, j):
        if coords is None:
            return 0.0
        a = coord_of(i)
        b = coord_of(j)
        if a is None or b is None:
            return 0.0
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return (dx * dx + dy * dy) ** 0.5

    unvisited = list(customers)
    unvisited.sort(key=lambda c: (dist(depot, c), -dem_get(c), c))

    routes = []
    while unvisited:
        route = []
        load = 0
        current = depot

        best_idx = None
        best_key = None
        for idx, c in enumerate(unvisited):
            d = dem_get(c)
            if d <= capacity:
                key = (dist(depot, c), -d, c)
                if best_key is None or key > best_key:
                    best_key = key
                    best_idx = idx
        if best_idx is None:
            best_idx = 0

        c = unvisited.pop(best_idx)
        route.append(c)
        load += dem_get(c)
        current = c

        while True:
            best_idx = None
            best_key = None
            for idx, cand in enumerate(unvisited):
                d = dem_get(cand)
                if load + d > capacity:
                    continue
                key = (dist(current, cand), dist(depot, cand), -d, cand)
                if best_key is None or key < best_key:
                    best_key = key
                    best_idx = idx
            if best_idx is None:
                break
            c = unvisited.pop(best_idx)
            route.append(c)
            load += dem_get(c)
            current = c

        routes.append(route)

    def route_load(route):
        s = 0
        for x in route:
            s += dem_get(x)
        return s

    def route_cost(route):
        if coords is None or not route:
            return 0.0
        total = dist(depot, route[0])
        for i in range(len(route) - 1):
            total += dist(route[i], route[i + 1])
        total += dist(route[-1], depot)
        return total

    if coords is not None:
        improved = True
        while improved:
            improved = False
            for r in routes:
                n = len(r)
                if n < 4:
                    continue
                changed = True
                while changed:
                    changed = False
                    best_delta = 0.0
                    best_i = best_j = None
                    for i in range(n - 2):
                        a = depot if i == 0 else r[i - 1]
                        b = r[i]
                        for j in range(i + 1, n - 1):
                            c = r[j]
                            d = depot if j + 1 == n else r[j + 1]
                            delta = (dist(a, c) + dist(b, d)) - (dist(a, b) + dist(c, d))
                            if delta < best_delta:
                                best_delta = delta
                                best_i, best_j = i, j
                    if best_i is not None:
                        segment = r[best_i:best_j + 1]
                        segment.reverse()
                        r[best_i:best_j + 1] = segment
                        changed = True
                        improved = True

    assigned = {}
    for r in routes:
        for c in r:
            assigned[c] = assigned.get(c, 0) + 1

    missing = [c for c in customers if assigned.get(c, 0) == 0]
    if missing:
        missing.sort(key=lambda c: (dist(depot, c), -dem_get(c), c))
        for c in missing:
            d = dem_get(c)
            best_route = None
            best_pos = None
            best_key = None
            for ridx, r in enumerate(routes):
                if route_load(r) + d > capacity:
                    continue
                if coords is None or not r:
                    key = (len(r), route_cost(r), ridx, 0)
                    pos = len(r)
                else:
                    pos = 0
                    local_best = None
                    for p in range(len(r) + 1):
                        left = depot if p == 0 else r[p - 1]
                        right = depot if p == len(r) else r[p]
                        inc = dist(left, c) + dist(c, right) - dist(left, right)
                        key2 = (inc, p)
                        if local_best is None or key2 < local_best:
                            local_best = key2
                            pos = p
                    key = (local_best[0], len(r), ridx, pos)
                if best_key is None or key < best_key:
                    best_key = key
                    best_route = ridx
                    best_pos = pos
            if best_route is None:
                routes.append([c])
            else:
                routes[best_route].insert(best_pos, c)

    repaired = []
    for r in routes:
        current = []
        load = 0
        for c in r:
            d = dem_get(c)
            if load + d <= capacity:
                current.append(c)
                load += d
            else:
                if current:
                    repaired.append(current)
                current = [c]
                load = d
        if current:
            repaired.append(current)

    final_routes = []
    seen = {}
    for r in repaired:
        nr = []
        load = 0
        for c in r:
            if seen.get(c, 0):
                continue
            d = dem_get(c)
            if load + d <= capacity:
                nr.append(c)
                load += d
                seen[c] = 1
        if nr:
            final_routes.append(nr)

    for c in customers:
        if seen.get(c, 0):
            continue
        d = dem_get(c)
        best_r = None
        best_p = None
        best_key = None
        for ridx, r in enumerate(final_routes):
            if route_load(r) + d > capacity:
                continue
            if coords is None or not r:
                key = (len(r), ridx, len(r))
                pos = len(r)
            else:
                pos = 0
                local_best = None
                for p in range(len(r) + 1):
                    left = depot if p == 0 else r[p - 1]
                    right = depot if p == len(r) else r[p]
                    inc = dist(left, c) + dist(c, right) - dist(left, right)
                    key2 = (inc, p)
                    if local_best is None or key2 < local_best:
                        local_best = key2
                        pos = p
                key = (local_best[0], ridx, pos)
            if best_key is None or key < best_key:
                best_key = key
                best_r = ridx
                best_p = pos
        if best_r is None:
            final_routes.append([c])
        else:
            final_routes[best_r].insert(best_p, c)
        seen[c] = 1

    return final_routes
